static int[] twoSumSorted(int[] arr, int target) {
    int l = 0, r = arr.length - 1;
    while (l < r) {
        int s = arr[l] + arr[r];
        if (s == target) return new int[]{l, r};
        else if (s < target) l++;
        else r--;
    }
    return null;
}
System.out.println(Arrays.toString(twoSumSorted(new int[]{1,2,3,4,6}, 6)));

