static int maxSumWindow(int[] arr, int k) {
    int window = 0;
    for (int i = 0; i < k; i++) window += arr[i];
    int best = window;
    for (int i = k; i < arr.length; i++) {
        window += arr[i] - arr[i - k];
        best = Math.max(best, window);
    }
    return best;
}
System.out.println(maxSumWindow(new int[]{1,2,3,4,5}, 2));

