static Set<Integer> dfs(Map<Integer, List<Integer>> graph, int node, Set<Integer> visited) {
    visited.add(node);
    for (int n : graph.get(node)) if (!visited.contains(n)) dfs(graph, n, visited);
    return visited;
}
Map<Integer, List<Integer>> graph = Map.of(1, List.of(2, 3), 2, List.of(), 3, List.of());
System.out.println(dfs(graph, 1, new HashSet<>()));

