static List<Integer> bfs(Map<Integer, List<Integer>> graph, int start) {
    Set<Integer> visited = new HashSet<>(List.of(start));
    Queue<Integer> q = new LinkedList<>(List.of(start));
    List<Integer> order = new ArrayList<>();
    while (!q.isEmpty()) {
        int node = q.poll();
        order.add(node);
        for (int n : graph.get(node)) if (visited.add(n)) q.add(n);
    }
    return order;
}
Map<Integer, List<Integer>> graph = Map.of(1, List.of(2, 3), 2, List.of(), 3, List.of());
System.out.println(bfs(graph, 1));

